package net.hivel.islandsrpg.listener;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.magic.MagicItemDefinition; import net.hivel.islandsrpg.stats.StatType; import net.hivel.islandsrpg.util.ColorUtil; import net.hivel.islandsrpg.weapon.*; import org.bukkit.Material; import org.bukkit.Sound; import org.bukkit.entity.*; import org.bukkit.event.*; import org.bukkit.event.entity.*; import org.bukkit.inventory.ItemStack; import org.bukkit.potion.*; import java.util.concurrent.ThreadLocalRandom;
public class CombatListener implements Listener { private final IslandsRPGPlugin p; public CombatListener(IslandsRPGPlugin p){this.p=p;} @EventHandler(ignoreCancelled=true) public void damage(EntityDamageByEntityEvent e){ if(e.getDamager() instanceof Player pl && e.getEntity() instanceof LivingEntity target){var d=p.data().get(pl); ItemStack hand=pl.getInventory().getItemInMainHand(); WeaponDefinition w=p.weapons().from(hand); MagicItemDefinition m=p.magic().from(hand); if(w!=null){ if(d.level<w.requiredLevel()){pl.sendMessage(ColorUtil.color(p.message("need-level").replace("%level%",String.valueOf(w.requiredLevel())))); return;} double dmg=w.damage()+d.stat(StatType.MELEE)*w.meleeScaling()+d.stat(StatType.SWORD)*w.swordScaling()+d.stat(StatType.MAGIC)*w.magicScaling(); if(w.type()==WeaponType.SWORD)dmg*=1+p.stats().damageBonus(d,StatType.SWORD); else dmg*=1+p.stats().damageBonus(d,StatType.MELEE); e.setDamage(dmg); if(w.passiveChance()>0&&ThreadLocalRandom.current().nextDouble(100)<w.passiveChance()) e.setDamage(e.getDamage()+w.passiveAmount()+d.stat(StatType.MAGIC)*w.passiveMagicScaling()); p.particles().hit(pl,target,w); if(w.hitSound()!=null)pl.playSound(pl.getLocation(),w.hitSound(),1,1); }
 if(m!=null){ long remain=p.magic().remaining(pl.getUniqueId(),m.id()); if(remain>0){pl.sendMessage(ColorUtil.color(p.message("cooldown").replace("%seconds%",String.valueOf((remain+999)/1000)))); return;} if(d.level<m.requiredLevel()){pl.sendMessage(ColorUtil.color(p.message("need-level").replace("%level%",String.valueOf(m.requiredLevel())))); return;} e.setDamage(m.damage()*(1+p.stats().magicBonus(d))+d.stat(StatType.MAGIC)*m.magicScaling()); if("BURN".equalsIgnoreCase(m.effectType())) target.setFireTicks(m.effectDurationSeconds()*20); if("SLOW".equalsIgnoreCase(m.effectType())) target.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS,m.effectDurationSeconds()*20,m.effectAmplifier())); p.magic().cooldown(pl.getUniqueId(),m.id(),m.cooldownSeconds()); p.particles().hit(pl,target,m); if(m.hitSound()!=null)pl.playSound(pl.getLocation(),m.hitSound(),1,1); }} if(e.getEntity() instanceof Player victim){var d=p.data().get(victim); e.setDamage(e.getDamage()*(1-p.stats().defenceReduction(d)));} if(e.getEntity() instanceof LivingEntity le && p.mobs().isCustom(le)){String id=p.mobs().id(le); var mob=p.mobs().get(id); if(mob!=null) p.getServer().getScheduler().runTaskLater(p,()->p.mobs().updateName(le,mob.displayName(),mob.health()),1); var boss=p.bosses().get(id); if(boss!=null)p.getServer().getScheduler().runTaskLater(p,()->{p.mobs().updateName(le,boss.displayName(),boss.health()); p.bossBars().update(le,boss);},1);} }
}
